/**
 * usePeekDetection — true owner-recognition peek guard.
 *
 * Pipeline (per detection tick, default ~300ms):
 *   1. Grab a frame from the hidden front-camera <video>.
 *   2. Run MediaPipe FaceLandmarker → list of faces with normalized embeddings.
 *   3. Filter out faces below `minFaceArea` (too far / specks).
 *   4. For each face, compute cosine similarity vs. enrolled owner embeddings
 *      (best-of-N). A face is "stranger" if best similarity < `matchThreshold`.
 *   5. Determine breach for *this frame*:
 *         • alertOnStranger        — any non-owner face visible
 *         • alertOnMultipleFaces   — total face count ≥ 2
 *         • alertOnNoFace          — zero faces (only when "stranger guard" is OK)
 *      The active alert modes are user-controlled in settings.
 *   6. Push the breach bool into a rolling buffer of `consistencyFrames`.
 *      Only when ALL frames in the buffer agree do we arm the lock timer.
 *   7. After `lockDelay`ms of continuous breach we surface `isPeeking = true`,
 *      which the PeekGuard component turns into a lock screen.
 *   8. `isPeeking` stays true until host code calls the returned `dismiss()`
 *      after the user actually authenticates/dismisses — nothing in this
 *      hook clears it on its own. Skipping that call is a real bug, not a
 *      cosmetic one: the lock-arming guard requires `!isPeeking`, so a
 *      forgotten dismiss() means no future breach can ever re-lock the
 *      screen for the rest of the session.
 *
 * No owner enrolled → falls back to count-based breach
 * (multi-face = breach; single face is fine).
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  detectFaces, loadOwnerProfile, matchAgainstOwnerPoseAware,
  type OwnerProfile,
} from "@/lib/faceRecognition";
import { detectFacesOffThread, isWorkerSupported, teardownFaceWorker } from "@/lib/faceWorkerClient";
import { subscribeCameraBus, explainGumError, acquireCamera, type CameraLease } from "@/lib/cameraBus";
import { Capacitor } from "@capacitor/core";
import { logPeekEvent, getFalseAlarmThresholdRelief } from "@/lib/peekEventLog";

/** requestVideoFrameCallback isn't in lib.dom.d.ts yet in all TS configs. */
type RVFCVideo = HTMLVideoElement & {
  requestVideoFrameCallback?: (cb: (now: number, meta: unknown) => void) => number;
  cancelVideoFrameCallback?: (handle: number) => void;
};

export interface PeekConfig {
  /** Cosine similarity threshold. ≥ this = owner. Default 0.7. */
  matchThreshold?: number;
  /** Min normalized face area (0..1). Below = ignored. Default 0.015 (~12%×12% of frame). */
  minFaceArea?: number;
  /** Number of consecutive frames the breach must be observed. Default 2.
   *  This is a deliberate anti-flicker gate, not lock latency — it's what
   *  keeps a single bad frame from locking the screen. Lock *speed* is
   *  governed by lockDelay below, not this. */
  consistencyFrames?: number;
  /** Delay after a *confirmed* (consistency-passed) breach before locking
   *  (ms). Default 150 — this is the "decision → blur → lock" leg of the
   *  pipeline, tuned to the ~100-150ms target now that detection itself
   *  runs off the main thread (see faceDetection.worker.ts) and no longer
   *  competes with the lock-screen's own render/animation work. */
  lockDelay?: number;
  /** Detection frequency in ms. Default 300. */
  checkInterval?: number;
  /** Trigger when a non-owner face is seen. Default true. */
  alertOnStranger?: boolean;
  /** Trigger when ≥ 2 faces are seen. Default true. */
  alertOnMultipleFaces?: boolean;
  /** Trigger when no face seen for the sustained window (see
   *  noFaceSustainMs). Default true — "owner walked away and left the
   *  device unattended" is a real breach case, not just stranger/crowd
   *  presence. Kept safe from false alarms by (a) noFaceSustainMs below,
   *  which requires the frame to be genuinely empty for a while, not just
   *  a momentary look-away, and (b) the existing low-light guard, which
   *  refuses to treat "too dark to see a face" as "no one is there". */
  alertOnNoFace?: boolean;
  /** How long (ms) the frame must show zero significant faces before
   *  "no-face" is even considered as a candidate breach reason. This is
   *  deliberately longer than the generic consistencyFrames/lockDelay
   *  confirmation pipeline used for stranger/multiple-face breaches,
   *  because briefly turning your head away from your own phone is normal
   *  and shouldn't read as "left the device" — only a genuinely sustained
   *  empty frame should. Default 2500ms. */
  noFaceSustainMs?: number;
  /** If a stranger-classified face shows NEITHER liveness signal (no
   *  blink, no head-pose micro-movement) for this long (ms), lock anyway
   *  with reason "spoof" instead of deferring indefinitely. Balances two
   *  failure modes: too short and a genuinely static background photo/
   *  poster can trigger a false lock; too long and a live stranger who
   *  happens not to blink or move goes undetected for that whole window.
   *  Default 6000. Set to 0 to disable this escalation (revert to the old
   *  defer-forever-without-liveness behavior). */
  staticStrangerTimeoutMs?: number;
}

const DEFAULTS: Required<PeekConfig> = {
  matchThreshold: 0.7,
  minFaceArea: 0.015,
  // BUG FIX ("peek guard shows false alarm"): 2 consistency frames at the
  // default ~300ms tick (faster still under the "movement/uncertain"
  // dynamic-FPS tier — as low as ~150ms) meant a single bad frame pair
  // from a lighting flicker, motion blur, or a half-turned head could
  // pass the "all frames agree" gate and arm the lock. Bumped to 3 frames
  // so a real breach still confirms in well under half a second, but one
  // noisy frame can no longer single-handedly trigger a lock.
  consistencyFrames: 3,
  lockDelay: 150,
  checkInterval: 300,
  alertOnStranger: true,
  alertOnMultipleFaces: true,
  // CHANGED (peek guard accuracy pass): was false. "Owner isn't there at
  // all" is one of the two conditions this guard should always cover per
  // product intent ("alarm only when someone is looking, OR the owner
  // isn't there") — leaving it off by default meant an unattended,
  // unlocked device sitting in the open never triggered anything. Safe to
  // default on now that it's gated by noFaceSustainMs below rather than
  // firing on the very next empty frame.
  alertOnNoFace: true,
  noFaceSustainMs: 2500,
  staticStrangerTimeoutMs: 6000,
};

/**
 * Rolls the frame's raw signals into a single 0-100 threat score. This is
 * a heuristic weighted sum, not a trained model — the weights are
 * deliberately conservative (a lone stranger frame lands "Medium", not
 * "Critical") since the score is meant for a dashboard/log readout, not
 * as an independent trigger — locking is still driven by the existing
 * breach/consistency/lockDelay pipeline above, this just quantifies it.
 */
// RESEARCH NOTE (gaze-aware threat scoring): published shoulder-surfing
// research consistently flags plain "an extra face is in frame" as a weak
// signal on its own — Brudy et al. 2014 and the PrivacyScout study (PETS
// 2022) both note a bystander's face being visible doesn't mean they're
// actually looking at the screen (someone passing behind the user in a
// hallway, a person at the next table not glancing over, etc.), and
// gaze-aware systems like EyeSpot (MobileHCI 2018) exist specifically to
// cut that false-positive rate. We don't have real gaze/eye-tracking here
// (needs higher resolution + calibration than a phone's front camera at
// arm's length reliably gives — the same limitation those papers call
// out) but DetectedFaceRaw.pose (faceMath.ts's computePose) already gives
// a cheap, already-computed head-orientation proxy for every face, at zero
// extra cost — previously only ever read for the *owner's* liveness check,
// never used to weight a *stranger's* actual severity. A face turned well
// away from the camera is, per that research, meaningfully less likely to
// be an active shoulder-surfer than one oriented toward it, so it now
// counts for less in the numeric score below (see facingStrangerCount vs.
// strangerCount at the call site). This ONLY changes the reported
// severity/dashboard number — see the note above computeThreatScore's
// original definition: the actual lock decision is still driven entirely
// by the breach/consistency/lockDelay pipeline, unaffected by this, so a
// face-oriented-away stranger still locks the screen exactly as before —
// this just stops it from being over-reported as "critical" the same way
// a stranger clearly staring at the screen is.
const computeThreatScore = (input: {
  strangerCount: number;
  /** Strangers whose head orientation is roughly toward the camera — a
   *  subset of strangerCount. See RESEARCH NOTE above. */
  facingStrangerCount: number;
  totalFaces: number;
  spoofSuspected: boolean;
  sustainedBreach: boolean;
  /** Weak pixel-texture heuristic — see faceMath.ts. Given a much smaller
   *  weight than spoofSuspected on purpose: unvalidated thresholds. */
  flatTextureSuspected?: boolean;
}): number => {
  let score = 0;
  if (input.strangerCount > 0) {
    // Full weight for strangers oriented toward the screen; a stranger
    // present-but-facing-away still adds *some* score (they could turn at
    // any moment) but at a fraction of the weight, per the research note
    // above — not zero, since orientation is a noisy proxy, not proof.
    const facingWeight = 40 + Math.min(20, (input.facingStrangerCount - 1) * 10);
    const awayCount = input.strangerCount - input.facingStrangerCount;
    const awayWeight = awayCount > 0 ? 15 + Math.min(10, (awayCount - 1) * 5) : 0;
    score += input.facingStrangerCount > 0 ? facingWeight : awayWeight;
  }
  if (input.totalFaces >= 2) score += Math.min(25, (input.totalFaces - 1) * 12);
  if (input.spoofSuspected) score += 30;
  if (input.sustainedBreach) score += 15;
  if (input.flatTextureSuspected) score += 10;
  return Math.max(0, Math.min(100, score));
};

// Approximate "is this head oriented roughly toward the camera" gate —
// same honesty caveat as faceMath.ts's texture heuristic: not validated
// against a real device/lighting matrix, deliberately conservative
// (generous cone) so it only excludes faces that are clearly turned away,
// not anyone slightly off-center. pose.yaw/pitch are the raw
// nose-vs-eye-midpoint / nose-vs-chin-midpoint deltas in normalized image
// coordinates (see faceMath.ts computePose) — NOT the same tiny
// micro-movement RANGE threshold used for liveness a few lines below,
// which measures change over time rather than absolute angle.
const FACING_YAW_THRESHOLD = 0.055;
const FACING_PITCH_THRESHOLD = 0.06;
const isFacingCamera = (pose: { yaw: number; pitch: number }): boolean =>
  Math.abs(pose.yaw) < FACING_YAW_THRESHOLD && Math.abs(pose.pitch) < FACING_PITCH_THRESHOLD;

const threatLevelFromScore = (score: number): PeekDetectionState["threatLevel"] =>
  score >= 80 ? "critical" : score >= 60 ? "high" : score >= 40 ? "medium" : score >= 20 ? "low" : "safe";

export interface PeekDetectionState {
  isPeeking: boolean;
  isActive: boolean;
  error: string | null;
  /** Total faces seen in the latest frame. */
  facesDetected: number;
  /** Strangers (non-owner) in the latest frame. */
  strangersDetected: number;
  /** True iff an owner profile is enrolled. */
  ownerEnrolled: boolean;
  /** Last reason that armed the lock. */
  reason: "stranger" | "multiple" | "no-face" | "spoof" | null;
  /** 0-100 rolling threat score — see computeThreatScore() below for inputs. */
  threatScore: number;
  /** Banded readout of threatScore, for UI/dashboard use. */
  threatLevel: "safe" | "low" | "medium" | "high" | "critical";
  /** id of the most recently logged event in lib/peekEventLog.ts, for
   *  attaching user feedback (accurate / false alarm) after the fact. */
  lastEventId: string | null;
  /** Dismiss the current alert / re-arm detection. */
  dismiss: () => void;
  /** Live internals snapshot for the opt-in debug HUD. */
  getDebugSnapshot: () => {
    usingWorker: boolean;
    effectiveIntervalMs: number;
    cameraCovered: boolean;
    tickInFlight: boolean;
    texture: { laplacianVar: number; lumaStdDev: number; suspected: boolean };
    brightness: number;
    frameQuality: number;
    crowdModeActive: boolean;
    consecutiveLocks: number;
  };
}

export const usePeekDetection = (
  enabled: boolean,
  config: PeekConfig = {},
): PeekDetectionState => {
  const cfg = { ...DEFAULTS, ...config };
  const cfgRef = useRef(cfg);
  cfgRef.current = cfg;

  const [isPeeking, setIsPeeking]               = useState(false);
  const [isActive, setIsActive]                 = useState(false);
  const [error, setError]                       = useState<string | null>(null);
  const [facesDetected, setFacesDetected]       = useState(0);
  const [strangersDetected, setStrangersDetected] = useState(0);
  const [ownerEnrolled, setOwnerEnrolled]       = useState(false);
  const [reason, setReason]                     = useState<PeekDetectionState["reason"]>(null);
  const [threatScore, setThreatScore]           = useState(0);
  const [threatLevel, setThreatLevel]           = useState<PeekDetectionState["threatLevel"]>("safe");
  const [lastEventId, setLastEventId]           = useState<string | null>(null);

  const videoRef    = useRef<HTMLVideoElement | null>(null);
  const leaseRef    = useRef<CameraLease | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lockTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ownerRef    = useRef<OwnerProfile | null>(null);
  // See getFalseAlarmThresholdRelief's doc comment — refreshed periodically
  // (not every tick; it reads/parses localStorage) rather than on a React
  // state dependency, so a person rating a lock mid-session actually
  // changes live detector behavior within a few seconds instead of only
  // taking effect on next mount.
  const falseAlarmReliefRef = useRef(0);
  const breachBuf   = useRef<boolean[]>([]);
  const reasonBuf   = useRef<NonNullable<PeekDetectionState["reason"]>[]>([]);
  // Monotonic timestamp for FaceLandmarker.detectForVideo — must always increase.
  const tsRef       = useRef<number>(0);
  const externallyPausedRef = useRef(false);
  // Liveness: rolling Eye-Aspect-Ratio history per detection.
  // Used to require a blink (EAR drop > 0.06) within ~3s of any "stranger" trigger.
  const earHistoryRef = useRef<{ ts: number; ear: number }[]>([]);
  const lastLivenessOkRef = useRef<number>(0);
  // Second, independent liveness channel: head-pose micro-movement. A
  // printed photo / phone-screen replay held in front of the camera has
  // near-zero pose variance even over several seconds; a real person
  // holding a phone naturally drifts a small amount continuously — this
  // fires far more often than blinks (~every 4s on average), so it closes
  // the gap where a live stranger who simply doesn't blink in time would
  // otherwise go undetected. See usePeekDetection's spoof-timeout comment
  // below for how the two channels combine.
  const poseHistoryRef = useRef<{ ts: number; yaw: number; pitch: number }[]>([]);
  // When a stranger has been visible with NEITHER liveness channel firing,
  // timestamp when that streak started — null while not in that state.
  const strangerNoLivenessSinceRef = useRef<number | null>(null);
  // Cooldown after a confirmed peek event so the screen doesn't immediately re-trigger.
  const cooldownUntilRef = useRef<number>(0);
  // Progressive cooldown: each consecutive lock increases the cooldown to
  // prevent alarm spam in persistent crowd scenarios. Decays only after a
  // genuinely calm period — see the BUG FIX comment at its increment site
  // in tick() for why an immediate per-clear reset didn't actually work.
  const consecutiveLocksRef = useRef<number>(0);
  // Last time `allBreach` was true — used to detect a genuinely calm
  // period (see CROWD_CALM_RESET_MS) rather than a momentary clear.
  const lastBreachAtRef = useRef<number>(0);
  // How long the environment must stay breach-free before a fresh lock
  // starts the progressive-cooldown streak back over from 8s. 5 minutes:
  // long enough that "dismissed and immediately still surrounded by the
  // same crowd" clearly doesn't qualify, short enough that leaving the
  // crowd for a genuine while gives a fresh start rather than staying
  // escalated for the rest of the day.
  const CROWD_CALM_RESET_MS = 5 * 60 * 1000;
  // Timestamp when the breach was first continuously confirmed — used for
  // sustained-breath tracking so we only log a lock after the threat has
  // been genuine for a meaningful duration, not a transient spike.
  const breachStartedAtRef = useRef<number | null>(null);
  // Timestamp when the lock timer was armed — used to log the *actual*
  // elapsed decision→lock time (can drift from the configured lockDelay
  // under real device load), not just the configured value verbatim.
  const lockArmedAtRef = useRef<number>(0);
  // Minimum sustained breach duration (ms) before allowing a lock to fire.
  // Prevents locking on a transient crowd flash (e.g. someone walking past
  // the camera for 1-2 frames). Default 600ms — real threats persist much
  // longer, transient ones clear within ~300ms at the default tick rate.
  const MIN_SUSTAINED_BREACH_MS = 600;
  // requestVideoFrameCallback handle, when supported — replaces setInterval
  // polling so detection is scheduled off an actual decoded frame instead
  // of an arbitrary timer tick.
  const rvfcHandleRef = useRef<number | null>(null);
  const lastDetectAtRef = useRef<number>(0);
  const usingWorkerRef = useRef<boolean>(isWorkerSupported());
  const tickInFlightRef = useRef(false);
  // Dynamic FPS: the interval scheduleLoop() actually throttles to, derived
  // fresh each tick from current signals (see the tail of tick() below).
  // Starts at the user's configured checkInterval ("normal" tier) and
  // widens/narrows from there — never overridden to something the user
  // didn't effectively ask for, just adapted around their baseline.
  const dynamicIntervalRef = useRef<number>(DEFAULTS.checkInterval);
  // Camera-covered detection: a tiny offscreen canvas samples average
  // frame brightness each tick. Near-total darkness sustained for a few
  // consecutive ticks means the lens is very likely physically covered
  // (finger, case, sticker) — skip the expensive detection call entirely
  // until it clears. This is a coarse heuristic (a dark room can trigger
  // it too), not a precise "object over camera" classifier.
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const canvasCtxRef = useRef<CanvasRenderingContext2D | null>(null);
  const coveredStreakRef = useRef(0);
  const cameraCoveredRef = useRef(false);
  // Environmental quality tracking: brightness, blur, and frame quality
  // measurements used to suppress breach detection in degraded conditions
  // where MediaPipe landmarks are unreliable (dark rooms, blurry frames,
  // faces at extreme angles, partially occluded faces).
  // EMA-smoothed brightness (0-255). Raw per-tick brightness is noisy
  // frame-to-frame (auto-exposure hunting, a hand passing near the lens,
  // JPEG-ish sensor noise in low light) which was flipping isLowLight/
  // isDimLight on and off tick-to-tick — and that flicker is exactly what
  // let a single "looks dark now" frame either wrongly suppress a real
  // breach or a single "looks bright now" frame wrongly let a low-light
  // false match through. Smoothed with a fast-ish alpha (0.4) so it still
  // tracks a genuine lights-on/lights-off change within ~1s, just not a
  // single noisy frame. The camera-covered check below intentionally uses
  // the RAW per-tick value, not this — physical covering should react
  // immediately, not after the EMA catches up.
  const brightnessRef = useRef(128); // last measured brightness (0-255)
  const frameQualityRef = useRef(1.0); // 0-1 composite quality score, EMA-smoothed (see qualityEmaRef below)
  // EMA backing store for frameQualityRef — same flicker problem as
  // brightness: any single blurry/dark/off-angle frame among otherwise-good
  // ones shouldn't single-handedly flip the low-quality gate, and
  // conversely one lucky sharp frame shouldn't single-handedly open it
  // during a genuinely bad stretch. Starts optimistic (1.0) so the very
  // first tick after Peek Guard turns on isn't gated before any real
  // measurement exists.
  const qualityEmaRef = useRef(1.0);
  // Timestamp when the current unbroken "zero significant faces" streak
  // began — null while at least one face is visible. Backs the
  // noFaceSustainMs gate (see PeekConfig doc comment) so a brief look-away
  // from your own phone doesn't read as "owner left the device".
  const noFaceSinceRef = useRef<number | null>(null);
  // Owner-match confidence tracking: when the owner IS in frame but the
  // match score is borderline (between the adaptive threshold and
  // threshold - 0.1), we don't immediately treat the face as a stranger.
  // Instead we track how many consecutive borderline frames we've seen —
  // only after a sustained period of borderline matches do we consider it
  // a real "owner not recognized" event. This prevents false breaches
  // when the owner's face is partially occluded, at an extreme angle, or
  // in poor lighting where the match score naturally degrades.
  const ownerBorderlineStreakRef = useRef(0);
  const OWNER_BORDERLINE_GRACE_MS = 3000; // 3s of borderline before treating as stranger
  // Rolling face-count history for crowd detection — see the "Crowd
  // detection" block in tick() for how this gates both breach paths.
  const crowdFaceHistoryRef = useRef<{ ts: number; count: number }[]>([]);
  const CROWD_WINDOW_MS = 8000;
  // "4" = owner + 3 others, sustained — a genuinely dense scene, not just
  // one extra person nearby (which is exactly the case this feature is
  // FOR catching, so the threshold has to stay well above 2).
  const CROWD_FACE_THRESHOLD = 4;
  // Latest crowdModeActive computed in tick() — mirrored into a ref purely
  // so getDebugSnapshot (a separate useCallback) can read it.
  const crowdModeActiveRef = useRef(false);
  // Latest texture-score reading (see faceMath.ts's textureScoreFromGrayscale
  // doc comment for what this actually is/isn't) — stored in a ref purely
  // for the debug HUD; the per-tick decision uses a local computed fresh
  // each tick, not this ref.
  const lastTextureRef = useRef<{ laplacianVar: number; lumaStdDev: number; suspected: boolean } | null>(null);

  // Load owner profile once / on enable, AND whenever it changes (enroll or
  // clear) while already running. Enrollment happens in Settings, separate
  // from the Peek Guard toggle — without this second listener, enrolling
  // your face while Peek Guard was already on left this hook holding a
  // stale/empty owner reference until you toggled it off/on or restarted
  // the app, so it kept treating you as unrecognized after enrolling.
  useEffect(() => {
    let cancelled = false;
    const reload = () => {
      loadOwnerProfile().then((p) => {
        if (cancelled) return;
        ownerRef.current = p;
        setOwnerEnrolled(!!p && p.count > 0);
      });
    };
    reload();
    window.addEventListener("duospace:owner-profile-changed", reload);
    return () => { cancelled = true; window.removeEventListener("duospace:owner-profile-changed", reload); };
  }, [enabled]);

  // Periodically refresh the false-alarm feedback relief (see
  // getFalseAlarmThresholdRelief) so rating locks during this session
  // actually changes live behavior, not just next app launch.
  useEffect(() => {
    if (!enabled) { falseAlarmReliefRef.current = 0; return; }
    const refresh = () => { falseAlarmReliefRef.current = getFalseAlarmThresholdRelief(); };
    refresh();
    const id = setInterval(refresh, 5000);
    return () => clearInterval(id);
  }, [enabled]);

  const teardown = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    if (rvfcHandleRef.current != null && videoRef.current) {
      (videoRef.current as RVFCVideo).cancelVideoFrameCallback?.(rvfcHandleRef.current);
    }
    rvfcHandleRef.current = null;
    tickInFlightRef.current = false;
    if (lockTimerRef.current) { clearTimeout(lockTimerRef.current); lockTimerRef.current = null; }
    if (leaseRef.current) { leaseRef.current.release(); leaseRef.current = null; }
    if (videoRef.current) { videoRef.current.srcObject = null; videoRef.current.remove(); videoRef.current = null; }      breachBuf.current = [];
    reasonBuf.current = [];
    earHistoryRef.current = [];
    poseHistoryRef.current = [];
    strangerNoLivenessSinceRef.current = null;
    consecutiveLocksRef.current = 0;
    breachStartedAtRef.current = null;
    lastBreachAtRef.current = 0;
    cameraCoveredRef.current = false;
    brightnessRef.current = 128;
    frameQualityRef.current = 1.0;
    qualityEmaRef.current = 1.0;
    noFaceSinceRef.current = null;
    ownerBorderlineStreakRef.current = 0;
    lastTextureRef.current = null;
    crowdFaceHistoryRef.current = [];
    canvasRef.current = null;
    canvasCtxRef.current = null;
    dynamicIntervalRef.current = cfgRef.current.checkInterval;
    setIsActive(false);
    setThreatScore(0);
    setThreatLevel("safe");
  }, []);

  const tick = useCallback(async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    // Cooldown after a recent confirmed peek event — avoid re-triggering immediately.
    if (Date.now() < cooldownUntilRef.current) return;

    // ── Camera-covered check (cheap, runs every tick) ──────────────────────
    // 8x8 downsample is sub-millisecond and lets us skip the ~15-30ms
    // MediaPipe call entirely while the lens is covered — the single
    // biggest per-tick cost, and the one most worth avoiding for battery.
    const canvas = canvasRef.current, ctx = canvasCtxRef.current;
    if (canvas && ctx) {
      try {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
        let sum = 0;
        for (let i = 0; i < data.length; i += 4) sum += (data[i] + data[i + 1] + data[i + 2]) / 3;
        const rawBrightness = sum / (data.length / 4); // 0-255, this tick only
        // Cover detection reacts to the RAW value — a finger over the lens
        // should register immediately, not wait on smoothing.
        if (rawBrightness < 6) {
          coveredStreakRef.current++;
          if (coveredStreakRef.current >= 3) cameraCoveredRef.current = true;
        } else {
          coveredStreakRef.current = 0;
          cameraCoveredRef.current = false;
        }
        // Everything downstream (isLowLight/isDimLight, low-light threshold
        // relaxation, dynamic FPS tiering) reads the EMA-smoothed value so a
        // single noisy frame can't flip the low-light classification —
        // see brightnessRef's doc comment above.
        brightnessRef.current = brightnessRef.current * 0.6 + rawBrightness * 0.4;
      } catch { /* transient — treat as not covered */ }
    }
    if (cameraCoveredRef.current) {
      setFacesDetected(0);
      setStrangersDetected(0);
      // Idle-tier polling while covered — just keep sampling brightness
      // cheaply until it clears, don't touch breach state at all (a
      // covered lens isn't itself a breach signal).
      dynamicIntervalRef.current = Math.max(cfgRef.current.checkInterval * 3, 800);
      return;
    }

    let faces;
    try {
      if (usingWorkerRef.current) {
        // Off-thread: capture + inference happen in faceDetection.worker.ts,
        // so this never blocks React's render loop or the lock-screen's
        // own blur/fade animation.
        faces = await detectFacesOffThread(video);
      } else {
        tsRef.current = Math.max(tsRef.current + 1, performance.now());
        faces = await detectFaces(video, tsRef.current);
      }
    } catch {
      // One bad frame (e.g. worker hiccup) shouldn't permanently disable
      // the pipeline — fall back to main-thread detection for future ticks.
      usingWorkerRef.current = false;
      return;
    }
    const c = cfgRef.current;

    const significant = faces.filter((f) => f.area >= c.minFaceArea);
    setFacesDetected(significant.length);

    // ── Frame quality assessment ─────────────────────────────────────────
    // Composite quality score (0-1) from multiple signals. Used to suppress
    // breach detection when the frame is too degraded for reliable matching.
    // False positives spike in these conditions, so silence is safer than
    // a noisy guess.
    const brightness = brightnessRef.current;
    const isLowLight = brightness < 30;       // dark room / night
    const isDimLight = brightness < 60;        // dim but not pitch dark
    const primaryFace = significant.length > 0
      ? significant.reduce((a, b) => (a.area > b.area ? a : b))
      : null;
    const isSmallFace = primaryFace ? primaryFace.area < 0.04 : false;  // face < 20%×20% of frame
    const isExtremeAngle = primaryFace
      ? Math.abs(primaryFace.pose.yaw) > 0.08 || Math.abs(primaryFace.pose.pitch) > 0.08
      : false;
    // Texture blur: high laplacian variance = sharp, low = blurry.
    const isBlurry = primaryFace?.textureScore
      ? primaryFace.textureScore.laplacianVar < 8
      : false;
    // Composite quality: starts at 1.0, each degradation factor reduces it.
    let quality = 1.0;
    if (isLowLight) quality *= 0.3;       // severe penalty in darkness
    else if (isDimLight) quality *= 0.6;  // moderate penalty in dim light
    if (isSmallFace) quality *= 0.5;      // face too far / too small
    if (isExtremeAngle) quality *= 0.6;   // head turned far from camera
    if (isBlurry) quality *= 0.5;         // motion blur / out of focus
    // Smooth quality over recent ticks (EMA, alpha 0.5) before it's allowed
    // to gate anything. A single blurry/dark/off-angle frame in an
    // otherwise-clear stretch (a hand swipe, a blink-timed motion blur
    // frame) used to instantly suppress breach detection for that tick,
    // and — the opposite failure — one lucky sharp frame during a
    // genuinely bad stretch (walking, dim room) used to instantly re-open
    // it. Neither should happen off one frame; the smoothed value tracks a
    // real condition change within ~2 ticks while absorbing single-frame
    // noise.
    qualityEmaRef.current = qualityEmaRef.current * 0.5 + quality * 0.5;
    frameQualityRef.current = qualityEmaRef.current;

    const now = Date.now();

    // ── Owner matching (moved ahead of liveness/texture — see below) ───────
    // This used to run AFTER the liveness/texture blocks, which meant both
    // anti-spoof channels tracked whichever face was simply LARGEST in
    // frame, not the face actually under suspicion. In the exact scenario
    // this feature exists to catch — owner visible (often closest to the
    // camera, so largest) PLUS a spoofed stranger photo/screen held up
    // elsewhere in frame — that bug had the owner's own genuine blinks and
    // micro-movements silently vouching for the *stranger's* liveness,
    // because both channels were reading the owner's face the whole time.
    // Computing strangerFaces here, before liveness/texture run, lets those
    // two blocks target the actual candidate stranger instead.
    let strangerCount = 0;
    let facingStrangerCount = 0; // subset of strangerCount oriented toward the camera — see RESEARCH NOTE above computeThreatScore
    let ownerBorderline = false; // true if owner IS in frame but match score is borderline
    const strangerFaces: typeof significant = [];
    if (ownerRef.current) {
      // In low-light conditions, relax the threshold slightly — MediaPipe
      // landmarks are noisier in the dark, so the owner's own match score
      // naturally drops. Without this, the owner gets misclassified as a
      // stranger every time the lights go down.
      const lowLightRelaxation = isLowLight ? 0.06 : isDimLight ? 0.03 : 0;

      for (const f of significant) {
        // matchAgainstOwnerPoseAware both scores the face — weighted toward
        // whichever enrolled angle is closest to this face's current pose,
        // when the profile has pose data (see faceRecognition.ts) — and
        // relaxes the threshold for off-angle (yaw OR pitch) faces. This
        // used to be split across a bare matchAgainstOwner() call plus a
        // hand-rolled threshold here, which meant the pose relaxation this
        // function already implements was never actually applied on the
        // live detection path — only yaw was ever considered, never pitch,
        // so an owner looking down at their own phone got none of the
        // off-angle tolerance a sideways glance did. Applying it here is
        // the fix for "owner is in frame but still gets flagged".
        const { score: sim, threshold: poseThreshold } = matchAgainstOwnerPoseAware(
          f.embedding, ownerRef.current, c.matchThreshold, f.pose.yaw, f.pose.pitch,
        );
        const adjustedThreshold = Math.max(
          0.45,
          poseThreshold - falseAlarmReliefRef.current - lowLightRelaxation,
        );
        if (sim < adjustedThreshold) {
          strangerCount++;
          strangerFaces.push(f);
          if (isFacingCamera(f.pose)) facingStrangerCount++;
        } else if (sim < adjustedThreshold + 0.1) {
          // Borderline: above threshold but close to it — the face looks
          // LIKE the owner but not confidently. Track this for grace period
          // handling below.
          ownerBorderline = true;
        }
      }
    }
    setStrangersDetected(strangerCount);

    // ── Owner-borderline grace period ────────────────────────────────────
    // When the owner IS in frame but the match score is borderline (common
    // in dark rooms, extreme angles, partial occlusion), don't immediately
    // treat it as a stranger. Track how long the borderline state persists —
    // only after OWNER_BORDERLINE_GRACE_MS of sustained borderline matches
    // do we count it as a real "owner not recognized" event. This prevents
    // false breaches when the owner's face is degraded but still visible.
    if (ownerBorderline && strangerCount === 0) {
      ownerBorderlineStreakRef.current += 1;
    } else {
      ownerBorderlineStreakRef.current = 0;
    }
    const borderlineTimeout = ownerBorderlineStreakRef.current > 0
      && (ownerBorderlineStreakRef.current * c.checkInterval) >= OWNER_BORDERLINE_GRACE_MS;
    // If borderline has timed out, reclassify the borderline face as a stranger
    // so the existing breach logic picks it up.
    if (borderlineTimeout && strangerCount === 0 && significant.length > 0 && ownerRef.current) {
      strangerCount = 1;
      strangerFaces.push(significant[0]);
      if (isFacingCamera(significant[0].pose)) facingStrangerCount = 1;
      ownerBorderlineStreakRef.current = 0; // reset after reclassification
    }

    // ── Liveness tracking (blink detection via EAR drop) ───────────────────
    // Tracks the largest STRANGER face when one is present — the face the
    // spoof check in the breach logic below actually cares about — and
    // falls back to the largest face overall only when no stranger is in
    // frame (matches prior behavior for that case, where the value is
    // unused by the breach logic anyway). A blink is a transient EAR drop
    // > 0.06 (open ~0.32 → closed ~0.18). When seen, mark "liveness OK" for
    // the next 4 seconds.
    const livenessTarget: (typeof significant)[number] | undefined =
      strangerFaces.length > 0
        ? strangerFaces.reduce((a, b) => (a.area > b.area ? a : b))
        : significant.length > 0
          ? significant.reduce((a, b) => (a.area > b.area ? a : b))
          : undefined;
    if (livenessTarget) {
      earHistoryRef.current.push({ ts: now, ear: livenessTarget.ear });
      // Keep last 2s only
      while (earHistoryRef.current.length && now - earHistoryRef.current[0].ts > 2000) {
        earHistoryRef.current.shift();
      }
      const hist = earHistoryRef.current;
      if (hist.length >= 4) {
        const maxE = Math.max(...hist.map((h) => h.ear));
        const minE = Math.min(...hist.map((h) => h.ear));
        if (maxE - minE > 0.06) lastLivenessOkRef.current = now;
      }

      // Second liveness channel: head-pose micro-movement over a 3s window.
      // Real people holding a phone drift continuously; a printed photo or
      // screen replay propped in front of the camera stays essentially
      // fixed. Threshold is deliberately small — this is meant to catch
      // "basically zero movement at all", not require a real head turn.
      poseHistoryRef.current.push({ ts: now, yaw: livenessTarget.pose.yaw, pitch: livenessTarget.pose.pitch });
      while (poseHistoryRef.current.length && now - poseHistoryRef.current[0].ts > 3000) {
        poseHistoryRef.current.shift();
      }
      const poseHist = poseHistoryRef.current;
      if (poseHist.length >= 5) {
        const yaws = poseHist.map((p) => p.yaw);
        const pitches = poseHist.map((p) => p.pitch);
        const yawRange = Math.max(...yaws) - Math.min(...yaws);
        const pitchRange = Math.max(...pitches) - Math.min(...pitches);
        if (yawRange > 0.006 || pitchRange > 0.006) lastLivenessOkRef.current = now;
      }
    }
    const livenessOk = now - lastLivenessOkRef.current < 4000;

    // ── Texture heuristic (weak, unvalidated — see faceMath.ts's
    // textureScoreFromGrayscale doc comment before trusting this) ─────────
    // Same stranger-targeting fix as the liveness block above — this is
    // also an anti-spoof signal, so it needs to read the candidate
    // stranger's face crop, not just whichever face is biggest. Deliberately
    // conservative placeholder thresholds, and deliberately requires BOTH
    // signals flat (not either alone) to reduce false positives from
    // ordinary blurry/dark frames. Feeds only into the threat score below,
    // never gates a lock directly — not confident enough in these
    // unvalidated numbers to let it lock someone's screen on its own.
    let flatTextureSuspected = false;
    if (livenessTarget?.textureScore) {
      const { laplacianVar, lumaStdDev } = livenessTarget.textureScore;
      flatTextureSuspected = laplacianVar < 15 && lumaStdDev < 8;
      lastTextureRef.current = { laplacianVar, lumaStdDev, suspected: flatTextureSuspected };
    } else {
      lastTextureRef.current = null;
    }

    let breach = false;
    let why: NonNullable<PeekDetectionState["reason"]> | null = null;
    let spoofSuspected = false;

    // ── Environmental quality gate ────────────────────────────────────────
    // When frame quality is too low for reliable matching (dark room,
    // blurry frame, face at extreme angle, face too small), suppress
    // breach detection entirely. False positives in these conditions are
    // far more likely than true positives — the owner's face itself looks
    // like a stranger when landmarks are noisy. We still track the state
    // (for the debug HUD and threat score) but don't arm the lock timer.
    const QUALITY_GATE_THRESHOLD = 0.4; // below this, don't breach
    // Gate on the EMA-smoothed value, not this tick's raw `quality` — see
    // qualityEmaRef's doc comment. Keeps a single bad/good frame from
    // flipping the gate on its own.
    const frameIsLowQuality = qualityEmaRef.current < QUALITY_GATE_THRESHOLD;

    // ── Crowd detection ───────────────────────────────────────────────────
    // Rolling average face count over a short window — a single busy frame
    // (someone briefly walking through the background) shouldn't count as
    // "a crowd", but a SUSTAINED high face count is a real signal that
    // this is a dense public space (train, café, mall) rather than a
    // targeted peek attempt, and both breach paths above raise their bar
    // accordingly while this is active. See the two FIX comments below.
    crowdFaceHistoryRef.current.push({ ts: now, count: significant.length });
    while (crowdFaceHistoryRef.current.length && now - crowdFaceHistoryRef.current[0].ts > CROWD_WINDOW_MS) {
      crowdFaceHistoryRef.current.shift();
    }
    const crowdWindow = crowdFaceHistoryRef.current;
    const crowdAvg = crowdWindow.length
      ? crowdWindow.reduce((sum, e) => sum + e.count, 0) / crowdWindow.length
      : 0;
    // Require the window to actually span most of CROWD_WINDOW_MS before
    // trusting the average — otherwise the very first couple of ticks
    // after Peek Guard turns on could read as "crowded" off 1-2 samples.
    const crowdWindowFilled = crowdWindow.length > 0 && (now - crowdWindow[0].ts) >= CROWD_WINDOW_MS * 0.6;
    const crowdModeActive = crowdWindowFilled && crowdAvg >= CROWD_FACE_THRESHOLD;
    crowdModeActiveRef.current = crowdModeActive;

    if (frameIsLowQuality && significant.length > 0) {
      // Frame is degraded but someone IS in frame — likely the owner in
      // bad conditions. Don't breach, don't arm the lock. Just wait for
      // conditions to improve.
      breach = false;
      why = null;
      strangerNoLivenessSinceRef.current = null;
      ownerBorderlineStreakRef.current = 0;
    } else if (c.alertOnStranger && ownerRef.current && strangerCount > 0) {
      // FIX ("crowd causes repeated alarms", biggest single lever): only
      // escalate liveness/spoof tracking when at least one stranger is
      // actually oriented toward the camera (facingStrangerCount) — see
      // the RESEARCH NOTE above computeThreatScore. Before this, ANY
      // non-owner face in frame counted, so a crowd where bystanders are
      // simply visible but facing every direction except the phone (the
      // overwhelmingly common case in a real crowd) still tripped this
      // branch on presence alone. Genuinely being watched requires
      // someone actually looking this way, not just being nearby.
      if (facingStrangerCount === 0) {
        strangerNoLivenessSinceRef.current = null;
      } else if (livenessOk) {
        breach = true; why = "stranger";
        strangerNoLivenessSinceRef.current = null;
      } else if (earHistoryRef.current.length < 6) {
        // Not enough history yet to judge liveness either way — same
        // permissive default the original code used, just for a shorter
        // window now that pose is a second, faster-firing channel.
        breach = true; why = "stranger";
        strangerNoLivenessSinceRef.current = null;
      } else {
        // Stranger present AND facing the camera, neither liveness
        // channel has fired. Defer the breach as a possible static
        // photo/poster — but only up to staticStrangerTimeoutMs, past
        // which persistent zero-movement presence is itself suspicious
        // enough to lock on, distinct from a confirmed live stranger.
        spoofSuspected = true;
        if (strangerNoLivenessSinceRef.current == null) strangerNoLivenessSinceRef.current = now;
        const elapsed = now - strangerNoLivenessSinceRef.current;
        if (c.staticStrangerTimeoutMs > 0 && elapsed >= c.staticStrangerTimeoutMs) {
          breach = true; why = "spoof";
        }
      }
    } else {
      strangerNoLivenessSinceRef.current = null;
      // FIX ("crowd causes repeated alarms"): in the default config
      // (alertOnStranger on), this branch almost never ran before — any
      // 2nd face nearly always failed the owner match and took the
      // stranger branch above instead, so "multiple faces" was mostly
      // dead code. Now that the stranger branch requires facing, a
      // genuinely dense but non-facing crowd can land here instead —
      // gate this on crowd size too (see crowdModeActive below), not just
      // a flat "≥2", so a bystander walking past in the background still
      // doesn't trip it on its own.
      const crowdAwareMultiThreshold = crowdModeActive ? (frameIsLowQuality ? 5 : 4) : (frameIsLowQuality ? 3 : 2);
      // FIX (same gap as the stranger branch above, now closed here too):
      // this used to count ANY significant faces toward the threshold,
      // including this path's own "no owner enrolled" fallback where every
      // face in frame is unclassified. A bystander visible in the
      // background but facing away from the screen isn't watching it —
      // require the threshold to be met by faces actually oriented toward
      // the camera, same isFacingCamera cone used for strangers. This is
      // the "only alarm when someone is looking" half of the product
      // requirement; the "or the owner isn't there" half is the no-face
      // branch below.
      const facingSignificant = significant.filter((f) => isFacingCamera(f.pose));
      if (c.alertOnMultipleFaces && facingSignificant.length >= crowdAwareMultiThreshold) {
        breach = true; why = "multiple";
      } else if (c.alertOnNoFace && significant.length === 0) {
        // In low light, face detection is unreliable — don't breach on
        // "no face" when it's probably just too dark to see. Require
        // sustained darkness (brightness < 20) for at least 5s before
        // treating "no face" as a real signal.
        if (!isLowLight || brightness < 20) {
          // Sustain gate: only count this as "owner not there" once the
          // frame has been continuously empty for noFaceSustainMs — a
          // normal head-turn away from your own phone shouldn't register
          // as "left the device". See noFaceSustainMs's doc comment.
          if (noFaceSinceRef.current == null) noFaceSinceRef.current = now;
          if (now - noFaceSinceRef.current >= c.noFaceSustainMs) {
            breach = true; why = "no-face";
          }
        }
      } else {
        noFaceSinceRef.current = null;
      }
    }
    if (significant.length > 0) noFaceSinceRef.current = null;

    breachBuf.current.push(breach);
    if (why) reasonBuf.current.push(why);
    if (breachBuf.current.length > c.consistencyFrames) breachBuf.current.shift();
    if (reasonBuf.current.length > c.consistencyFrames) reasonBuf.current.shift();

    const allBreach = breachBuf.current.length === c.consistencyFrames &&
                      breachBuf.current.every(Boolean);

    // Track sustained breach duration for progressive cooldown gating.
    // BUG FIX ("crowd causes repeated alarms"): this used to reset
    // consecutiveLocksRef the instant a breach cleared — but a breach
    // clears almost immediately after every lock, because the person is
    // now looking at their OWN unlock screen (camera sees the owner again,
    // not the crowd), not because the crowd actually left. That reset the
    // "progressive" cooldown back to its 8s floor on literally every
    // dismissal, so in a real crowd (train, cafe, mall) it never actually
    // escalated — it just kept re-locking every 8s indefinitely, which is
    // exactly the "shows the alarm again and again" complaint. Fixed by
    // only decaying the streak after a genuinely calm period (no breach at
    // all for CROWD_CALM_RESET_MS) rather than on every momentary clear —
    // so a string of locks minutes apart while stuck in the same crowd
    // keeps escalating, and it only resets once the person has actually
    // been somewhere breach-free for a while.
    if (allBreach) {
      if (breachStartedAtRef.current == null) breachStartedAtRef.current = now;
      lastBreachAtRef.current = now;
    } else {
      breachStartedAtRef.current = null;
      if (now - lastBreachAtRef.current >= CROWD_CALM_RESET_MS) {
        consecutiveLocksRef.current = 0;
      }
    }

    const score = computeThreatScore({
      strangerCount, facingStrangerCount, totalFaces: significant.length, spoofSuspected, sustainedBreach: allBreach,
      flatTextureSuspected,
    });
    setThreatScore(score);
    setThreatLevel(threatLevelFromScore(score));

    // ── Dynamic FPS ──────────────────────────────────────────────────────
    // Tiers scale off the user's own configured checkInterval (their
    // chosen "normal" baseline) rather than hardcoded absolutes, so a
    // battery-conscious user's slower setting stays slower across every
    // tier, not just the normal one. Floors keep the fast tiers from
    // trying to poll faster than a worker round-trip can actually finish.
    // In low-light conditions, detection is unreliable — slow down to save
    // battery and avoid noisy results. In very dark environments, detection
    // is essentially useless so we go even slower.
    const baseline = c.checkInterval;
    if (isLowLight) {
      // Too dark for reliable detection — poll at minimum useful rate.
      dynamicIntervalRef.current = Math.round(baseline * 4);
    } else if (score >= 60 || why === "spoof") {
      // Threat — confirm/lock as fast as reasonably possible.
      dynamicIntervalRef.current = Math.max(80, Math.round(baseline * 0.25));
    } else if (strangerCount > 0 || significant.length >= 2 || spoofSuspected) {
      // Movement / uncertain — something's actively changing, poll faster
      // to resolve it (confirm real breach or clear the flicker) sooner.
      dynamicIntervalRef.current = Math.max(100, Math.round(baseline * 0.5));
    } else if (significant.length === 0) {
      // Idle — nobody in frame at all.
      dynamicIntervalRef.current = Math.round(baseline * 2.5);
    } else {
      // Normal — owner steadily present, nothing ambiguous.
      dynamicIntervalRef.current = isDimLight ? Math.round(baseline * 1.5) : baseline;
    }

    if (allBreach) {
      const r = reasonBuf.current[reasonBuf.current.length - 1] ?? "stranger";
      if (!lockTimerRef.current && !isPeeking) {
        // Sustained-breach gate: don't arm the lock timer until the breach
        // has been continuously confirmed for at least this long. Prevents
        // locking on transient crowd flashes (someone walking past, a
        // quick reflection) while still locking quickly on genuine
        // sustained threats. Doubled while crowdModeActive — a dense scene
        // makes momentary false "facing" reads (e.g. two people briefly
        // aligned with the camera axis as they cross paths) more likely,
        // so it's worth waiting for firmer confirmation specifically there.
        const requiredSustainMs = crowdModeActive ? MIN_SUSTAINED_BREACH_MS * 2 : MIN_SUSTAINED_BREACH_MS;
        const sustainedDuration = breachStartedAtRef.current != null
          ? now - breachStartedAtRef.current
          : 0;
        if (sustainedDuration < requiredSustainMs) return;

        lockArmedAtRef.current = Date.now();
        lockTimerRef.current = setTimeout(() => {
          setReason(r);
          setIsPeeking(true);
          consecutiveLocksRef.current++;
          const id = logPeekEvent({
            reason: r,
            threatScore: score,
            timeToLockMs: Date.now() - lockArmedAtRef.current,
          });
          setLastEventId(id);
          // Progressive cooldown: 8s base + 4s per consecutive lock, capped
          // at 5 minutes. Uncapped-at-60s (the original version of this)
          // meant a long train ride or busy café would still re-lock every
          // minute for its whole duration — 5 minutes is long enough to
          // actually stop being a nuisance once the streak is genuinely
          // established, while the 8s/12s/16s... early ramp still means a
          // real one-off threat gets re-checked quickly if it recurs.
          const progressiveMs = Math.min(5 * 60 * 1000, 8000 + consecutiveLocksRef.current * 4000);
          cooldownUntilRef.current = Date.now() + progressiveMs;
        }, c.lockDelay);
      }
    } else if (lockTimerRef.current) {
      clearTimeout(lockTimerRef.current);
      lockTimerRef.current = null;
    }
  }, [isPeeking]);

  const stopLoop = useCallback(() => {
    if (intervalRef.current) { clearInterval(intervalRef.current); intervalRef.current = null; }
    if (rvfcHandleRef.current != null && videoRef.current) {
      (videoRef.current as RVFCVideo).cancelVideoFrameCallback?.(rvfcHandleRef.current);
    }
    rvfcHandleRef.current = null;
  }, []);

  /**
   * Drives detection off requestVideoFrameCallback (fires exactly when a new
   * decoded frame is presented) instead of a free-running setInterval, so
   * we're never racing a frame that hasn't actually updated yet. Throttled
   * to `dynamicIntervalRef` — a battery-aware interval recomputed at the
   * end of every tick() from that tick's own signals (idle/normal/
   * movement/threat — see the "Dynamic FPS" block in tick()). Falls back
   * to a fixed setInterval at the user's configured checkInterval on
   * WebViews that don't support rVFC — the dynamic tiering only applies
   * to the rVFC path since a plain setInterval's delay is fixed at
   * creation and can't cheaply be re-armed every tick.
   */
  const scheduleLoop = useCallback(() => {
    stopLoop();
    const video = videoRef.current as RVFCVideo | null;
    if (!video) return;

    if (typeof video.requestVideoFrameCallback === "function") {
      const onFrame = () => {
        const now = performance.now();
        if (!tickInFlightRef.current && now - lastDetectAtRef.current >= dynamicIntervalRef.current) {
          lastDetectAtRef.current = now;
          tickInFlightRef.current = true;
          Promise.resolve(tick()).finally(() => { tickInFlightRef.current = false; });
        }
        rvfcHandleRef.current = video.requestVideoFrameCallback!(onFrame);
      };
      rvfcHandleRef.current = video.requestVideoFrameCallback(onFrame);
    } else {
      intervalRef.current = setInterval(tick, cfgRef.current.checkInterval);
    }
  }, [stopLoop, tick]);

  const start = useCallback(async () => {
    if (isActive || externallyPausedRef.current) return;
    setError(null);

    if (typeof window !== "undefined" && !window.isSecureContext) {
      setError("Camera requires HTTPS. Open the app over a secure connection.");
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      setError("This browser does not support camera access.");
      return;
    }

    try {
      const video = document.createElement("video");
      video.setAttribute("playsinline", "");
      video.setAttribute("autoplay", "");
      video.muted = true;
      video.style.cssText = "position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0;pointer-events:none;";
      document.body.appendChild(video);
      videoRef.current = video;

      const canvas = document.createElement("canvas");
      canvas.width = 8;
      canvas.height = 8;
      canvasRef.current = canvas;
      canvasCtxRef.current = canvas.getContext("2d", { willReadFrequently: true });
      coveredStreakRef.current = 0;
      cameraCoveredRef.current = false;
      dynamicIntervalRef.current = cfgRef.current.checkInterval;

      const lease = await acquireCamera("user");
      leaseRef.current = lease;
      video.srcObject = lease.stream;
      await video.play().catch(() => { /* autoplay restrictions handled below by readyState gate */ });

      // Warm up whichever pipeline will actually serve detection, so the
      // first real tick isn't ~1s slow waiting on model load.
      usingWorkerRef.current = isWorkerSupported();
      try {
        if (usingWorkerRef.current) {
          await detectFacesOffThread(video).catch(() => { /* model still loading, first real tick will retry */ });
        } else {
          await (await import("@/lib/faceRecognition")).getLandmarker();
        }
      } catch { /* network */ }

      tsRef.current = 0;
      lastDetectAtRef.current = 0;
      scheduleLoop();
      setIsActive(true);
    } catch (err) {
      const exp = explainGumError(err);
      setError(exp.message);
      teardown();
    }
  }, [isActive, scheduleLoop, teardown]);

  // enable/disable lifecycle
  useEffect(() => {
    if (enabled) {
      start();
    } else {
      teardown();
      // Only free the ~3MB model + worker thread on a real disable, not on
      // the transient teardowns used for camera-bus handoff or tab-hide —
      // those resume quickly and would otherwise pay the reload cost.
      teardownFaceWorker();
    }
    return () => teardown();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled]);

  // Yield camera ownership when another flow (e.g. enrollment dialog) requests it.
  useEffect(() => {
    if (!enabled) return;
    const unsub = subscribeCameraBus((p) => {
      externallyPausedRef.current = p;
      if (p) {
        teardown();
      } else if (enabled && !isActive) {
        setTimeout(() => { if (!externallyPausedRef.current) start(); }, 250);
      }
    });
    return unsub;
  }, [enabled, isActive, start, teardown]);

  // Re-arm the frame loop if checkInterval changes (throttle is read live
  // from cfgRef inside the rVFC callback, but the setInterval fallback path
  // needs re-arming since its delay is fixed at creation time).
  useEffect(() => {
    if (!isActive) return;
    scheduleLoop();
    return () => stopLoop();
  }, [cfg.checkInterval, isActive, scheduleLoop, stopLoop]);

  // ── Auto on/off around backgrounding ───────────────────────────────────
  // Two tiers, both driven from the same `onHide`/`onShow` pair below:
  //   1. Brief hide (< BACKGROUND_RELEASE_MS) — e.g. pulling down the
  //      notification shade, a quick app-switcher glance — just pauses the
  //      frame loop (stopLoop). Camera + worker stay warm so resuming is
  //      instant, matching the previous behavior for these short blips.
  //   2. Sustained hide (≥ BACKGROUND_RELEASE_MS) — the app is genuinely
  //      backgrounded — fully tears down: releases the camera lease, so
  //      the OS camera indicator actually turns off and the hardware stops
  //      drawing power, rather than "peek guard" itself becoming exactly
  //      the kind of always-on camera use a privacy feature should avoid.
  //      On return to foreground this calls start() again (re-acquire +
  //      re-warm) instead of just re-arming the loop. This is the "auto
  //      turning itself on and off" behavior — no manual toggle involved.
  const BACKGROUND_RELEASE_MS = 4000;
  const bgReleaseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fullyReleasedRef = useRef(false);

  // Reset the auto on/off bookkeeping whenever the guard is fully disabled
  // (or unmounted) so a stale "fully released, needs full restart" flag
  // from a previous session doesn't linger into the next enable.
  useEffect(() => {
    if (enabled) return;
    fullyReleasedRef.current = false;
    if (bgReleaseTimerRef.current) { clearTimeout(bgReleaseTimerRef.current); bgReleaseTimerRef.current = null; }
  }, [enabled]);

  const onHide = useCallback(() => {
    stopLoop();
    if (bgReleaseTimerRef.current) clearTimeout(bgReleaseTimerRef.current);
    bgReleaseTimerRef.current = setTimeout(() => {
      bgReleaseTimerRef.current = null;
      if (document.hidden || externallyPausedRef.current) {
        fullyReleasedRef.current = true;
        teardown();
      }
    }, BACKGROUND_RELEASE_MS);
  }, [stopLoop, teardown]);

  const onShow = useCallback(() => {
    if (bgReleaseTimerRef.current) { clearTimeout(bgReleaseTimerRef.current); bgReleaseTimerRef.current = null; }
    if (externallyPausedRef.current) return;
    if (fullyReleasedRef.current) {
      fullyReleasedRef.current = false;
      start(); // full re-acquire: camera was actually released while backgrounded
    } else if (isActive && !intervalRef.current && rvfcHandleRef.current == null) {
      scheduleLoop();
    }
  }, [isActive, scheduleLoop, start]);

  useEffect(() => {
    if (!enabled) return;
    const onVis = () => { if (document.hidden) onHide(); else onShow(); };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      document.removeEventListener("visibilitychange", onVis);
      if (bgReleaseTimerRef.current) { clearTimeout(bgReleaseTimerRef.current); bgReleaseTimerRef.current = null; }
    };
  }, [enabled, onHide, onShow]);

  // Native (Capacitor) app backgrounding — `visibilitychange` isn't always
  // reliable inside a native WebView when the screen locks or the app is
  // swapped away, so this is a second, more direct signal on native
  // platforms specifically. Web builds rely on visibilitychange alone.
  useEffect(() => {
    if (!enabled || !Capacitor.isNativePlatform()) return;
    let remove: (() => void) | undefined;
    let cancelled = false;
    (async () => {
      try {
        const { App } = await import("@capacitor/app");
        const sub = await App.addListener("appStateChange", ({ isActive: appIsActive }) => {
          if (!appIsActive) onHide(); else onShow();
        });
        if (cancelled) { sub.remove(); return; }
        remove = () => sub.remove();
      } catch { /* plugin unavailable — visibilitychange still covers it */ }
    })();
    return () => { cancelled = true; remove?.(); };
  }, [enabled, onHide, onShow]);

  /**
   * Clears the current peek state so a future breach can re-arm. This was
   * a real gap: nothing in this hook ever called setIsPeeking(false), and
   * the lock-arming guard (`!lockTimerRef.current && !isPeeking`) meant
   * once a single lock had ever fired, isPeeking stayed true for the rest
   * of the session and no subsequent breach — however real — could ever
   * lock the screen again. Host code (PeekGuard) must call this once the
   * user has actually dismissed/authenticated past a lock.
   */
  const dismiss = useCallback(() => {
    setIsPeeking(false);
    setReason(null);
    breachBuf.current = [];
    reasonBuf.current = [];
    breachStartedAtRef.current = null;
    if (lockTimerRef.current) { clearTimeout(lockTimerRef.current); lockTimerRef.current = null; }
    // Progressive cooldown on dismiss: use the same escalating scale as the
    // lock timer path. First dismiss = 3s, then 6s, 10s, 16s, capped at 30s.
    // This prevents the old behavior where dismiss() set a flat 1s cooldown
    // that allowed immediate re-lock in persistent crowd scenarios.
    const dismissCooldownMs = Math.min(30000, 3000 + consecutiveLocksRef.current * 3000);
    cooldownUntilRef.current = Date.now() + dismissCooldownMs;
  }, []);

  /**
   * Snapshot of live internals for an opt-in debug HUD (PeekGuard renders
   * one when appSettings.peekDebugMode is on). Deliberately a plain
   * function returning a fresh object rather than React state — polling
   * refs on a timer only when the debug HUD is actually mounted means
   * users who never enable it pay zero extra re-render cost for this.
   */
  const getDebugSnapshot = useCallback(() => ({
    usingWorker: usingWorkerRef.current,
    effectiveIntervalMs: dynamicIntervalRef.current,
    cameraCovered: cameraCoveredRef.current,
    tickInFlight: tickInFlightRef.current,
    texture: lastTextureRef.current,
    brightness: brightnessRef.current,
    frameQuality: frameQualityRef.current,
    crowdModeActive: crowdModeActiveRef.current,
    consecutiveLocks: consecutiveLocksRef.current,
  }), []);

  return {
    isPeeking, isActive, error,
    facesDetected, strangersDetected, ownerEnrolled, reason,
    threatScore, threatLevel, lastEventId, dismiss, getDebugSnapshot,
  };
};
